const _INITIAL_RE = re.compile(`(?=[${UP}])${nlb(`${WC}'.`)}([${UP}])\\.(?=${S}+[${UP}])`, has('.'));
const _SENTENCE_SPLIT_RE = re.compile(`(?<=[.!?])${S}+`, null, false);

