  url: [_URL_RE, _URL_SRC],
  email: [_EMAIL_RE, _EMAIL_SRC],
  alnum: [_ALNUM_RE, _ALNUM_SRC],
  leftover: [re.compile(`(?<![${LET}])([${LET}]+)\\.(?=${D})`), `([${LET}]+)\\.(?=${D})`],
